sp_widget.client_script:
api.controller = function() {

    var c = this;

    /*
     * =========================================
     * INITIALIZE
     * =========================================
     */

    c.selectedStudent =
        c.data.studentId || '';

    c.selectedEvent = '';

    c.loading = false;


    /*
     * =========================================
     * ANALYZE WITH NASK
     * =========================================
     */

    c.analyze = function() {

        if (!c.selectedStudent || !c.selectedEvent) {

            c.data.message =
                'Please select an event.';

            c.data.matchResult = '';

            return;
        }


        c.loading = true;

        c.data.message =
            'Connecting to Campus Connect NASK...';

        c.data.matchResult = '';


        var ga = new GlideAjax(
            'x_snc_campus_con_0.CampusConnectAISkillMatcher'
        );


        ga.addParam(
            'sysparm_name',
            'analyze'
        );


        ga.addParam(
            'sysparm_student',
            c.selectedStudent
        );


        ga.addParam(
            'sysparm_event',
            c.selectedEvent
        );


        ga.getXMLAnswer(function(answer) {

            console.log(
                'Campus Connect NASK Response:',
                answer
            );


            c.loading = false;


            if (!answer) {

                c.data.message =
                    'NASK returned an empty response.';

                c.data.matchResult = '';

                return;
            }


            try {

                var result =
                    JSON.parse(answer);


                console.log(
                    'Parsed NASK Response:',
                    result
                );


                if (result.success === true) {

                    c.data.message =
                        result.message ||
                        'NASK analysis completed successfully.';

                    c.data.matchResult =
                        result.matchResult || '';

                } else {

                    c.data.message =
                        result.message ||
                        'NASK execution failed.';

                    c.data.matchResult = '';

                }


            } catch (e) {

                c.data.message =
                    'Unable to parse NASK response.';

                c.data.matchResult =
                    answer;


                console.log(
                    'NASK Parse Error:',
                    e
                );

            }

        });

    };

};

sp_widget.css:
.cc-ai-matcher {
    max-width: 1200px;
    margin: 30px auto;
    padding: 0 20px 50px 200px;
    font-family: Arial, sans-serif;
}


/* =========================
   HEADER
   ========================= */

.matcher-header {
    display: flex;
    align-items: center;
    gap: 18px;

    padding: 26px 28px;
    margin-bottom: 22px;

    border-radius: 14px;

    background: linear-gradient(
        135deg,
        #17365d,
        #245b8f
    );

    color: #ffffff;

    box-shadow: 0 5px 18px rgba(0,0,0,0.12);
}

.header-icon {
    width: 58px;
    height: 58px;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 14px;

    background: rgba(255,255,255,0.16);

    font-size: 25px;
}

.header-content h2 {
    margin: 0 0 6px;

    font-size: 26px;
    font-weight: 600;
}

.header-content p {
    margin: 0;

    font-size: 14px;

    opacity: 0.9;
}


/* =========================
   SELECTION CARD
   ========================= */

.matcher-form {
    background: #ffffff;

    border: 1px solid #e1e7ef;

    border-radius: 14px;

    padding: 26px;

    box-shadow: 0 4px 16px rgba(0,0,0,0.06);
}

.section-title {
    font-size: 17px;
    font-weight: 600;

    color: #17365d;

    margin-bottom: 22px;

    padding-bottom: 12px;

    border-bottom: 1px solid #edf1f5;
}

.section-title i {
    margin-right: 8px;
}


/* =========================
   FORM
   ========================= */

.form-group {
    margin-bottom: 20px;
}

.form-group label {
    display: block;

    margin-bottom: 8px;

    color: #26364a;

    font-size: 14px;

    font-weight: 600;
}

.form-group label i {
    margin-right: 6px;

    color: #245b8f;
}

.form-control {
    width: 100%;

    height: 46px;

    padding: 8px 13px;

    border: 1px solid #cbd5e1;

    border-radius: 8px;

    background: #ffffff;

    font-size: 14px;

    color: #26364a;

    transition: all 0.2s ease;
}

.form-control:focus {
    border-color: #245b8f;

    outline: none;

    box-shadow:
        0 0 0 3px rgba(36,91,143,0.10);
}


/* =========================
   ANALYZE BUTTON
   ========================= */

.analyze-btn {
    width: 100%;

    height: 48px;

    border: none;

    border-radius: 8px;

    background: #245b8f;

    color: #ffffff;

    font-size: 15px;

    font-weight: 600;

    cursor: pointer;

    transition: all 0.2s ease;
}

.analyze-btn:hover:not(:disabled) {
    background: #17365d;

    transform: translateY(-1px);

    box-shadow: 0 4px 12px rgba(23,54,93,0.20);
}

.analyze-btn:disabled {
    opacity: 0.55;

    cursor: not-allowed;
}

.analyze-btn i {
    margin-right: 8px;
}


/* =========================
   LOADING
   ========================= */

.matcher-loading {
    display: flex;

    align-items: center;

    gap: 15px;

    margin-top: 20px;

    padding: 18px 20px;

    border-radius: 10px;

    background: #f4f7fa;

    border: 1px solid #dce5ee;

    color: #334155;
}

.loading-icon {
    width: 42px;
    height: 42px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #e4edf6;

    color: #245b8f;

    font-size: 19px;
}

.matcher-loading strong {
    display: block;

    margin-bottom: 4px;
}

.matcher-loading p {
    margin: 0;

    font-size: 13px;

    color: #64748b;
}


/* =========================
   MESSAGE
   ========================= */

.matcher-message {
    display: flex;

    align-items: center;

    gap: 10px;

    margin-top: 18px;

    padding: 15px 18px;

    border-radius: 9px;

    background: #f8fafc;

    border: 1px solid #dbe4ee;

    color: #475569;

    font-size: 14px;
}

.matcher-message i {
    color: #245b8f;

    font-size: 17px;
}


/* =========================
   AI RESULT
   ========================= */

.ai-result {
    margin-top: 24px;

    background: #ffffff;

    border: 1px solid #d9e3ec;

    border-radius: 14px;

    overflow: hidden;

    box-shadow: 0 5px 18px rgba(0,0,0,0.07);
}


/* Result Header */

.result-header {
    display: flex;

    align-items: center;

    justify-content: space-between;

    padding: 20px 22px;

    background: #f4f7fa;

    border-bottom: 1px solid #dfe7ef;
}

.result-title {
    display: flex;

    align-items: center;

    gap: 13px;
}

.result-icon {
    width: 42px;
    height: 42px;

    display: flex;

    align-items: center;
    justify-content: center;

    border-radius: 50%;

    background: #e3f3e9;

    color: #21854a;

    font-size: 17px;
}

.result-title h3 {
    margin: 0 0 4px;

    font-size: 18px;

    color: #17365d;
}

.result-title p {
    margin: 0;

    font-size: 12px;

    color: #64748b;
}


/* AI Badge */

.ai-badge {
    padding: 7px 11px;

    border-radius: 20px;

    background: #e8f0f8;

    color: #245b8f;

    font-size: 12px;

    font-weight: 600;
}

.ai-badge i {
    margin-right: 5px;
}


/* Result Body */

.result-body {
    padding: 22px;
}


/* Explanation Box */

.result-intro {
    display: flex;

    gap: 12px;

    padding: 16px;

    margin-bottom: 18px;

    border-radius: 9px;

    background: #f8fafc;

    border: 1px solid #e5ebf1;
}

.result-intro > i {
    font-size: 20px;

    color: #245b8f;

    margin-top: 2px;
}

.result-intro strong {
    display: block;

    margin-bottom: 5px;

    color: #26364a;
}

.result-intro p {
    margin: 0;

    color: #64748b;

    font-size: 13px;

    line-height: 1.5;
}


/* NASK Response */

.nask-response {
    border: 1px solid #dce5ee;

    border-radius: 10px;

    overflow: hidden;
}

.response-title {
    padding: 13px 16px;

    background: #f1f5f9;

    border-bottom: 1px solid #dce5ee;

    color: #17365d;

    font-weight: 600;

    font-size: 14px;
}

.response-title i {
    margin-right: 7px;
}

.response-content {
    padding: 20px;

    background: #ffffff;
}

.response-content pre {
    margin: 0;

    padding: 0;

    white-space: pre-wrap;

    word-wrap: break-word;

    background: transparent;

    border: none;

    font-family: Arial, sans-serif;

    font-size: 14px;

    line-height: 1.7;

    color: #26364a;
}


/* Footer */

.result-footer {
    padding: 13px 20px;

    background: #fafbfd;

    border-top: 1px solid #e5ebf1;

    color: #64748b;

    font-size: 12px;

    line-height: 1.5;
}

.result-footer i {
    margin-right: 6px;

    color: #245b8f;
}


/* =========================
   MOBILE
   ========================= */

@media (max-width: 600px) {

    .cc-ai-matcher {
        margin: 15px auto;

        padding: 0 12px 30px;
    }

    .matcher-header {
        padding: 20px;

        gap: 13px;
    }

    .header-icon {
        width: 48px;
        height: 48px;

        font-size: 20px;
    }

    .header-content h2 {
        font-size: 21px;
    }

    .matcher-form {
        padding: 20px;
    }

    .result-header {
        align-items: flex-start;

        gap: 12px;

        flex-direction: column;
    }

    .ai-badge {
        align-self: flex-start;
    }

}

sp_widget.script:
(function() {

    data.studentId = '';
    data.studentName = '';
    data.events = [];
    data.matchResult = '';
    data.message = '';

    /*
     * =========================================
     * CURRENT LOGGED-IN USER
     * =========================================
     */

    var currentUser = gs.getUserID();

    if (!currentUser) {

        data.message =
            'Unable to identify the logged-in student.';

        return;
    }


    /*
     * =========================================
     * LOAD ONLY CURRENT USER STUDENT PROFILE
     * =========================================
     */

    var studentProfile = new GlideRecord(
        'x_snc_campus_con_0_student_profile'
    );

    studentProfile.addQuery(
        'student',
        currentUser
    );

    studentProfile.setLimit(1);
    studentProfile.query();


    if (studentProfile.next()) {

        data.studentId =
            studentProfile.getValue('student');

        data.studentName =
            studentProfile.getDisplayValue('student');

    } else {

        data.message =
            'Student Profile not found for the logged-in user.';

        return;
    }


    /*
     * =========================================
     * LOAD VERIFIED EVENTS
     * =========================================
     */

    var eventGr = new GlideRecord(
        'x_snc_campus_con_0_events'
    );

    eventGr.addQuery(
        'verification_status',
        'verified'
    );

    eventGr.orderBy('event_date');
    eventGr.query();


    while (eventGr.next()) {

        data.events.push({

            sys_id:
                eventGr.getUniqueValue(),

            name:
                eventGr.getValue('event_name')

        });

    }

})();
